var indexedDB = window.indexedDB || window.mozIndexedDB || window.webkitIndexedDB || window.msIndexedDB || window.shimIndexedDB;

var open = indexedDB.open("file_system", 1);

open.onupgradeneeded = function() {
    var db = open.result;
    var store = db.createObjectStore("mainStore", {keyPath: "id"});
};

open.onsuccess = function() {
    var db = open.result;
    var tx = db.transaction("mainStore", "readwrite");
    var store = tx.objectStore("mainStore");

    store.put({id: "do not read.txt", data: "Wow... The audacity.. Prepare for destruction!"});
    store.put({id: "video.mp4", data: "data:video/mp4;base64,"});
    store.put({id: "cattuh.png", data: "data:video/png;base64,"});
}

function fsAddFile(name, data) {
  var db = open.result;
  var tx = db.transaction("mainStore", "readwrite");
  var store = tx.objectStore("mainStore");

  store.put({id: name, data: data});
}